\u006a\u0048\u0056\u0058\u0022\u0066\u0046\u005c\u003c\u003a\u002d\u002a\u0076\u002b\u0074\u0022\u0059\u004e\u0077\u004a\u0037\u0030\u0048\u002b\u0031\u0057\u0036\u003a\u004d\u002c\u0040\u002f\u0028\u003e\u002a\u0057\u002d\u0048\u0032\u0033\u007e\u004d\u002a\u0065\u0030\u0036\u002f\u0072\u005d\u0075\u0078\u007b\u003a\u006a\u0074\u0062\u0038\u0075\u0051\u0046\u0052\u005e\u0069\u003b\u0020\u0049\u003f\u007c\u003c\u002b\u0044\u0036\u002b\u0053\u0024\u0042\u0067\u0034\u005a\u006a\u006a\u0053\u002d\u007a\u0033\u004a\u0063\u0046\u0046\u004f\u0035\u004e\u0076\u002a\u007e\u0026\u0039\u0059\u0071\u005f\u0035\u0070\u0021\u0024\u0049\u003b\u0066\u0047\u0068\u0042\u005c\u005a\u0038\u0076\u004b\u0064\u0020\u003d\u0065\u0042\u0021\u005e\u003a\u0078\u0039\u004b\u0063\u0040\u006a\u0043\u004b\u006c\u0031\u004f\u0038\u0075\u002c\u0049\u007c\u003a\u005a\u0036\u0048\u0051\u0068\u005c\u0063\u0073\u0072\u002d\u007d\u0037\u0023\u0051\u0072\u006a\u005f\u0075\u004e\u0057\u0062\u0077\u0065\u002b\u0071\u006d\u004b\u0024\u005d\u004e\u002a\u004c\u004c\u003e\u0065\u0055\u0067\u0056\u0064\u0074\u0038\u002b\u005d\u007a\u006f\u0029\u0044\u003c\u007a\u0044\u0034\u0070\u0024\u006b\u0025\u0021\u002c\u005c\u0032\u004f\u0077\u002a\u0055\u0032\u0073\u007a\u0054\u002e\u0021\u0053\u0060\u006a\u0023\u006e\u0066\u0045\u0039\u0062\u004b\u004f\u003d\u003e\u002f\u0042\u0040\u0034\u0046\u0046\u004f\u0046\u0050\u0030\u0036\u005a\u0035\u0078\u003c\u0077\u0054\u0055\u003c\u0047\u0057\u002f\u004c\u0078\u004e\u0063\u006c\u0048\u0073\u0055\u003f\u0073\u007a\u002b\u0031\u0053\u0049\u0028\u0065\u0049\u006e\u007e\u0039\u0065\u0039\u0062\u003f\u0050\u004f\u007a\u0064\u005e\u0037\u0073\u003d\u005d\u004e\u005e\u002f\u0057\u0075\u003a\u002b\u0055\u005e\u0072\u0022\u002e\u006e\u0042\u005a\u0051\u0072\u007a\u005d\u0055\u006b\u0030\u005f\u0045\u003c\u0066\u002f\u0033\u0027\u0069\u0067\u0065\u0056\u0065\u0061\u0075\u007d\u002e\u0052\u0061\u004c\u0051\u007d\u0025\u0023\u0056\u005e\u004d\u0024\u007c\u0068\u0029\u0029\u006e\u006d\u006f\u0059\u0053\u006f\u004f\u0054\u0064\u004f\u0051\u006c\u0050\u002e\u0052\u0079\u0046\u004c\u004c\u005e\u004e\u0022\u0064\u0077\u003a\u0075\u0064\u0032\u0040\u002d\u0052\u003d\u0036\u0021\u0072\u007e\u005d\u0043\u002b\u0076\u0037\u0056\u0048\u0057\u0078\u0050\u005d\u0044\u004d\u0036\u0049\u0053\u0023\u0052\u0046\u0066\u0074\u0050\u0074\u0042\u0068\u0069\u004b\u0042\u0050\u002c\u0034\u0051\u0023\u0050\u0064\u0048\u0048\u0026\u0068\u0057\u0077\u006d\u007a\u0073\u007c\u0065\u0047\u0068\u002d\u0077\u0032\u004e\u0063\u0058\u005d\u0067\u0026\u0049\u0047\u0050\u0048\u004c\u0029\u0030\u0061\u002e\u0059\u0079\u005e\u0044\u0051\u0068\u003c\u004c\u0039\u0071\u006e\u0074\u0035\u002a\u0052\u0065\u0052\u005d\u0026\u0038\u0037\u0049\u003d\u006e\u0028\u004c\u0044\u004d\u0048\u006e\u0035\u005f\u006a\u0071\u007a\u0058\u0041\u0029\u002e\u0064\u0026\u0032\u006f\u0076\u0025\u0062\u004f\u0059\u0020\u0071\u006f\u0054\u0036\u007b\u006a\u005c\u0068\u0025\u0076\u0059\u0044\u004d\u0037\u0054\u0073\u006f\u003c\u006a\u0050\u0033\u003b\u006b\u0076\u0047\u0032\u007c\u0030\u007d\u0065\u0027\u0044\u0035\u002e\u0069\u0029\u006d\u0055\u002e\u0059\u007a\u0054\u0039\u0074\u003f\u007b\u0066\u004e\u003a\u007c\u0036\u0071\u0029\u0030\u004c\u0066\u0026\u0058\u0075\u0024\u0070\u0078\u0068\u0049\u0067\u006b\u007d\u0068\u0052\u002e\u0069\u002c\u002e\u0048\u0061\u0055\u0049\u0046\u0041\u0077\u0065\u0059\u0049\u006b\u0045\u0073\u0079\u0022\u0054\u006a\u005d\u0052\u006f\u0020\u0054\u007d\u0032\u005e\u002c\u0021\u0044\u0026\u0048\u003c\u003d\u0063\u003d\u007d\u0064\u006e\u0065\u004b\u0064\u004e\u0043\u0078\u0068\u0056\u0039\u0055\u006a\u0046\u0064\u0076\u002f\u0040\u005c\u004c\u003c\u0070\u0059\u005b\u004b\u0059\u0026\u0049\u0033\u005c\u0029\u007c\u0072\u003d\u0055\u0065\u0072\u0067\u0070\u007e\u004e\u007e\u0050\u0053\u0061\u003a\u005e\u0045\u0050\u0038\u007a\u0034\u0065\u005f\u0064\u0055\u0038\u0030\u002c\u0066\u0024\u005f\u004c\u0053\u0054\u004e\u003f\u0050\u002b\u0058\u0041\u0045\u0045\u002c\u0028\u0058\u002e\u0029\u0044\u0055\u0026\u006f\u0062\u006b\u0032\u0046\u007c\u004b\u0046\u0058\u004e\u0057\u007c\u0036\u0036\u0049\u0072\u006a\u0054\u0040\u0042\u0072\u0049\u0057\u0035\u0028\u0050\u0067\u0029\u0049\u0031\u0032\u0076\u0060\u0031\u0055\u0024\u0077\u0064\u0037\u0026\u0042\u002d\u0020\u0067\u0057\u0069\u002e\u002d\u0047\u0027\u0053\u0032\u005e\u0033\u0032\u0039\u0059\u0076\u0023\u0051\u0055\u0046\u006d\u006c\u0063\u0024\u0034\u006f\u002d\u0060\u007a\u007a\u005b\u004f\u0068\u004f\u003d\u0028\u0057\u0072\u003c\u007d\u0040\u0077\u006e\u006a\u0062\u0055\u0060\u0060\u002b\u0027\u0042\u003b\u0022\u0074\u0040\u0035\u0055\u006a\u005e\u0036\u0048\u0063\u0063\u002c\u0051\u0048\u0053\u002c\u0074\u0056\u005b\u0073\u0059\u0068\u007d\u0075\u0021\u0072\u0041\u0069\u0043\u0030\u0037\u0065\u002f\u006c\u0078\u006f\u003f\u0035\u0029\u006a\u0049\u006e\u0059\u0042\u004f\u0071\u0038\u003a\u0061\u0025\u0026\u003b\u002f\u005c\u003b\u003b\u0048\u002e\u004b\u007a\u002a\u0049\u0062\u0025\u0027\u0028\u0028\u003a\u0021\u005f\u0073\u0062\u0065\u0059\u0020\u003f\u002a\u0044\u004f\u0075\u0038\u005d\u0037\u004c\u007c\u004b\u004f\u006c\u006d\u002d\u0030\u0054\u0048\u004e\u002a\u003c\u002c\u005f\u0062\u007d\u0023\u004a\u0061\u0043\u004f\u0059\u0029\u006d\u004b\u0039\u005f\u0064\u0043\u0043\u002f\u0066\u0062\u002d\u0023\u0049\u005e\u0061\u0052\u0065\u0063\u0046\u0063\u0024\u0036\u0059\u0022\u0068\u007a\u002c\u004d\u002d\u004c\u0035\u0032\u007e\u0028\u007d\u0030\u005f\u0020\u0036\u003d\u0072\u002c\u0079\u0040\u003d\u004c\u0068\u0069\u002c\u004f\u0059\u004d\u004f\u0061\u0050\u0041\u0071\u0079\u0066\u004d\u003d\u002a\u002f\u004d\u003c\u0065\u002a\u003d\u0072\u006f\u002e\u004f\u0073\u0054\u002c\u0070\u0046\u0057\u006e\u0040\u0026\u006f\u0027\u007e\u003f\u0053\u0054\u004f\u002a\u0066\u0038\u0037\u0078\u0021\u0061\u006c\u002d\u006d\u0023\u0055\u0031\u0039\u006a\u0069\u002e\u006a\u0055\u0078\u0079\u0045\u0022\u004a\u0079\u004e\u0046\u005c\u0035\u004d\u002c\u0033\u004c\u005e\u0059\u0037\u006f\u007e\u007e\u0037\u0037\u0068\u0056\u0054\u0039\u0020\u003d\u0051\u007d\u0030\u005d\u0067\u003a\u007c\u003f\u0033\u0072\u005f\u005d\u0064\u0041\u0041\u0069\u0061\u002a\u0060\u0026\u0039\u0038\u0068\u005d\u007a\u004c\u0037\u0025\u0022\u003c\u002e\u0039\u007e\u004a\u004a\u0020\u004c\u0060\u0033\u0068\u0031\u0050\u0063\u0050\u006e\u0070\u0025\u006c\u0034\u0059\u005d\u003c\u0060\u005e\u007e\u003b\u0026\u0032\u0078\u007c\u005f\u0069\u0065\u004d\u0074\u0071\u0054\u0044\u005b\u0044\u007a\u006c\u0064\u0051\u005d\u0034\u0078\u0075\u002a\u0068\u004a\u003f\u0077\u0050\u006e\u0064\u006a\u0073\u002d\u004d\u0072\u0061\u0045\u0057\u004b\u004d\u004e\u006a\u0043\u0030\u0046\u0069\u0054\u0045\u0042\u002d\u0074\u0029\u004a\u002e\u007e\u0026\u002c\u0031\u0066\u007d\u0035\u0056\u0042\u007b\u0025\u0060\u0063\u0026\u0067\u0069\u004a\u0047\u006d\u0041\u0047\u0056\u003c\u0072\u006f\u0067\u006c\u005c\u007d\u0032\u0024\u0031\u0063\u0024\u0061\u004e\u0075\u0077\u004a\u0047\u0023\u0050\u0046\u0076\u0079\u0054\u002a\u006d\u0077\u0055\u0064\u007d\u005b\u002d\u005b\u0027\u005f\u0038\u0078\u0071\u0029\u002b\u0038\u0067\u003f\u0073\u006e\u0032\u0046\u005f\u0038\u0025\u0067\u0070\u002a\u003d\u0055\u007e\u006e\u0032\u003f\u007b\u0037\u005f\u006a\u006e\u0064\u007d\u002c\u007c\u004a\u0027\u0036\u007d\u0057\u005c\u005d\u002e\u0064\u0068\u0046\u0047\u0029\u006f\u006c\u004c\u0042\u006b\u0045\u005b\u006d\u004d\u002f\u0032\u006b\u005e\u004d\u006e\u0060\u006a\u0039\u0045\u0067\u0035\u0021\u0049\u005f\u0079\u0052\u003c\u0025\u0071\u0065\u007e\u007c\u0052\u0023\u005c\u0047\u0058\u004b\u004a\u0025\u0037\u0054\u0033\u006a\u0032\u0027\u0021\u0074\u007a\u0060\u0059\u0066\u0026\u005b\u0051\u007c\u0025\u006d\u006e\u003a\u0045\u0038\u003a\u007e\u0038\u0024\u0027\u0061\u002b\u0030\u004b\u0037\u0055\u006f\u0039\u003c\u004e\u0055\u002b\u0066\u006c\u0067\u0026\u002b\u007b\u006d\u002f\u0066\u0050\u0079\u0045\u0059\u0060\u003c\u007c\u002b\u0040\u0075\u0038\u002b\u0026\u006f\u004b\u0037\u0057\u0048\u0034\u0061\u002d\u0069\u0063\u0063\u0024\u0023\u005e\u0037\u0062\u0028\u003b\u0034\u0051\u003a\u003b\u007c\u004e\u0055\u0031\u0039\u007b\u002b\u005b\u0047\u0074\u0040\u004b\u004b\u0071\u006a\u0025\u0030\u0066\u007a\u0060\u005c\u0070\u0024\u006f\u0054\u003f\u005b\u004c\u0078\u0045\u0073\u0055\u003b\u0070\u0034\u003a\u0064\u0060\u0056\u004a\u005a\u003b\u004d\u0027\u0039\u0079\u0024\u004c\u0042\u004f\u0042\u006b\u0043\u002a\u0027\u0076\u0069\u006f\u0066\u0059\u0047\u0053\u0045\u006a\u007d\u0031\u005d\u0046\u0060\u0062\u0037\u005d\u007b\u0020\u002c\u0024\u005b\u007b\u004d\u0075\u0058\u0037\u0048\u005c\u006f\u0025\u002b\u0026\u0030\u0036\u005a\u0043\u003b\u0026\u002a\u0078\u0042\u0060\u006c\u002e\u002e\u0065\u003f\u0025\u0040\u006c\u003a\u003c\u0023\u0027\u0055\u0043\u0060\u0055\u005d\u0030\u0045\u0073\u003e\u0049\u002a\u0049\u004d\u007e\u0057\u0072\u002a\u0044\u005c\u0077\u005a\u003b\u0037\u0070\u005e\u0022\u003d\u005e\u002c\u004a\u0062\u0050\u0051\u0042\u0058\u003e\u0054\u0058\u006d\u002d\u0073\u007c\u0069\u0046\u0077\u007d\u0024\u003d\u0029\u002e\u0050\u007a\u005e\u002f\u0075\u003d\u0038\u0076\u0037\u0047\u004c\u0038\u005e\u0052\u005d\u0057\u0057\u006a\u0029\u004e\u006a\u003c\u007d\u003b\u0034\u0061\u005e\u002c\u002c\u0079\u0055\u0031\u005f\u0042\u0022\u007e\u0074\u005a\u0047\u0074\u0032\u005a\u003b\u0035\u0028\u0051\u0035\u004c\u006c\u003d\u006e\u005f\u0046\u0078\u006b\u005c\u0077\u0071\u002c\u0070\u0022\u0029\u006b\u0044\u0026\u0024\u0023\u003f\u005b\u0023\u0039\u002d\u004a\u0068\u0071\u0027\u0058\u007a\u002c\u005e\u0024\u0051\u0025\u0039\u004d\u0077\u0043\u0047\u006a\u003a\u0067\u0039\u006a\u0029\u006a\u006c\u0068\u0040\u004e\u0047\u0077\u0048\u007e\u0076\u007d\u002a\u002b\u0041\u0059\u0044\u0053\u0056\u0047\u002a\u0075\u0058\u004a\u006e\u0032\u0045\u006d\u0022\u007b\u004a\u0038\u007a\u0077\u004d\u0079\u0043\u0034\u0020\u0045\u004a\u0066\u004d\u0068\u0040\u0022\u005e\u007b\u0028\u0076\u0049\u0079\u0027\u0025\u006d\u0058\u0055\u0023\u0053\u0045\u0077\u004e\u0072\u0040\u0058\u006b\u0069\u003a\u0055\u007e\u0024\u006b\u0058\u0046\u004c\u003a\u0026\u0073\u0020\u0053\u0066\u003a\u0058\u0073\u004f\u0040\u0037\u0042\u0034\u0025\u004a\u0035\u006d\u0031\u006d\u004a\u004c\u0032\u0047\u0039\u003b\u004a\u0057\u0064\u0047\u004b\u006e\u0062\u0061\u007a\u0024\u005b\u007e\u0025\u005f\u0053\u0066\u005f\u002c\u0029\u006a\u0059\u003b\u007a\u006c\u0075\u0031\u0037\u0049\u0025\u0051\u0028\u005d\u0031\u004f\u002f\u0023\u0070\u0078\u005f\u0049\u005c\u0061\u007c\u0045\u0062\u005c\u0061\u0036\u0036\u0029\u0078\u0061\u0062\u0034\u0079\u0022\u003e\u004c\u0049\u0062\u007c\u007b\u007c\u0044\u006b\u0064\u0076\u005d\u0042\u003c\u0036\u0070\u0025\u006e\u0042\u0078\u006d\u0075\u005b\u0037\u0047\u0031\u003e\u0030\u0070\u0066\u0024\u0036\u0077\u0073\u0040\u0042\u003b\u005c\u0066\u0037\u0062\u004c\u006f\u0030\u003d\u002b\u0075\u0067\u002f\u006f\u0041\u0062\u006e\u005c\u006a\u0067\u0079\u0067\u007c\u0069\u002a\u005c\u0040\u0076\u0028\u0020\u0026\u0042\u0062\u0073\u0048\u0061\u006e\u0047\u0039\u0059\u0043\u0062\u0043\u0031\u0064\u0043\u0031\u004e\u0045\u0023\u0072\u002e\u0044\u0062\u002e\u0026\u0029\u0042\u0050\u005d\u007b\u003c\u0026\u007b\u006e\u006d\u0057\u0050\u005d\u004d\u004c\u0073\u0057\u0048\u0026\u0061\u0062\u0073\u0038\u003f\u0060\u005d\u0027\u003d\u0048\u0049\u0076\u0043\u002a\u0070\u0033\u0026\u0070\u006c\u006c\u0025\u0022\u0043\u0054\u0043\u0034\u0059\u007c\u0028\u006a\u003b\u0047\u007c\u0071\u005e\u0032\u0064\u0049\u0067\u0054\u0061\u0042\u0043\u0020\u0045\u005f\u003d\u0065\u004a\u0044\u007d\u0060\u0051\u0062\u004d\u0034\u0072\u004e\u005d\u006d\u0039\u006d\u0042\u0048\u005a\u0058\u002a\u005a\u0032\u0074\u0063\u0063\u002a\u002d\u0025\u0053\u0026\u005f\u0031\u0059\u0021\u0072\u0037\u0056\u0026\u0032\u005b\u0037\u004a\u0039\u0045\u0059\u0039\u005c\u0028\u0073\u002f\u006c\u0062\u0021\u0045\u006b\u003d\u004d\u0065\u0048\u003d\u0053\u0032\u0059\u0058\u005f\u004d\u002a\u0036\u007a\u002c\u0061\u0053\u005e\u006c\u007b\u0031\u0022\u002c\u004e\u004a\u0033\u003e\u0024\u007b\u003b\u0037\u0050\u0073\u0073